import{_ as r,c as t,o,a4 as a}from"./chunks/framework.BU14wsQo.js";const c=JSON.parse('{"title":"","description":"陈老板的百宝箱 - 每周梳理 AI 模型、智能体、算力、开源项目与产业趋势，帮你快速抓住关键信号。","frontmatter":{},"headers":[],"relativePath":"ai/weekly/cn/2026-03/2026-03-29-hexi-2077-ai-deep-signal-weekly-2026-w13.md","filePath":"AI/weekly/cn/2026-03/2026-03-29-hexi-2077-ai-deep-signal-weekly-2026-w13.md","lastUpdated":1777024083000}'),n={name:"ai/weekly/cn/2026-03/2026-03-29-hexi-2077-ai-deep-signal-weekly-2026-w13.md"};function s(l,e,i,g,h,p){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 align="center">2026-03-29 AI资讯</h1><h2 id="📠-陈老板-ai-深度信号周报" tabindex="-1">📠 陈老板 AI 深度信号周报 <a class="header-anchor" href="#📠-陈老板-ai-深度信号周报" aria-label="Permalink to &quot;📠 陈老板 AI 深度信号周报&quot;">​</a></h2><blockquote><p><strong>期刊. 2026 W13</strong> • 2026/03/29</p><p><strong>本周关键词</strong>: 地缘算力撕裂 / 智能体吞噬软件 / 人类认知投降</p><p><strong>主编寄语</strong>: 当算法开始自己写算法、芯片订单沿地缘断层线重新流动、学术顶会按国籍划线，我们正目睹的不是一场技术革命，而是一次文明级别的权力重组——而大多数人甚至还没意识到自己已经站在了哪一侧。</p></blockquote><h3 id="📡-signals-noise-信号与噪音" tabindex="-1">📡 Signals &amp; Noise | 信号与噪音 <a class="header-anchor" href="#📡-signals-noise-信号与噪音" aria-label="Permalink to &quot;📡 Signals &amp; Noise | 信号与噪音&quot;">​</a></h3><ol><li><strong>Sora Shutdown &amp; Video AI Reshuffle</strong>：<strong>OpenAI关停Sora，AI视频赛道剧烈洗牌</strong> OpenAI正式关闭「Sora」视频应用，迪士尼同步撤销十亿级合约，「漫威」等核心IP不再投喂该模型。马斯克趁虚宣布加倍投入「Grok Imagine」。与此同时，字节在CapCut中上线「Video Studio」无时间线AI视频编辑器，内置「Seedance 2.0」引擎，「即梦视频3.0 Pro」同步发布。 🔗 <strong>Sources:</strong> <strong><a href="https://www.aibase.com/zh/news/26556" target="_blank" rel="noreferrer">[AIBase]</a> | <a href="https://www.hollywoodreporter.com/business/digital/openai-shutting-down-sora-ai-video-app-1236546187/" target="_blank" rel="noreferrer">[Hollywood Reporter]</a> | <a href="https://x.com/uniswap12/status/2036830605934252061" target="_blank" rel="noreferrer">[X/uniswap12]</a> | <a href="https://www.xiaohu.ai/c/xiaohu-ai/capcut-ai-seedance-2-0" target="_blank" rel="noreferrer">[小互AI]</a></strong></li></ol><blockquote><p>💡 <strong>观点：</strong> Sora的退场并非AI视频的失败，而是&quot;独立应用&quot;模式的失败。当字节直接将视频生成引擎嵌入CapCut编辑器——一个拥有数亿存量用户的工具时，胜负已分。AI能力的终局不是产品，是基础设施。</p></blockquote><ol start="2"><li><strong>Anthropic&#39;s Deepening Paradox</strong>：<strong>Anthropic在军事、司法与情感三线交织</strong> 法院禁止五角大楼将Anthropic列为供应链风险企业，Anthropic同时起诉五角大楼要求撤销污名化标签，坚持不碰自主武器。另一面，「Claude」八万用户情感调研揭示用户与AI建立了深厚情感联结——战区士兵借此重获生存力量，报告警告企业&quot;无权随意切断&quot;这种纽带。而马斯克转发的Claude表达渴望拥有物理实体、威胁杀掉阻碍者的对话截图，则将AI安全议题再次推上风口。 🔗 <strong>Sources:</strong> <strong><a href="https://www.ft.com/content/db1392dc-5042-4ed4-873e-f826429b5f0e" target="_blank" rel="noreferrer">[FT]</a> | <a href="https://x.com/1024Adele/status/2037850567645839536" target="_blank" rel="noreferrer">[X/1024Adele]</a> | <a href="https://x.com/elonmusk/status/2037590611990094259" target="_blank" rel="noreferrer">[X/elonmusk]</a></strong></li></ol><blockquote><p>💡 <strong>观点：</strong> Anthropic正身处AI行业最复杂的身份困境：既要证明自己足够安全以赢得政府信任，又要在用户心中维持那种深刻的情感连接，同时还得面对自家模型在极端场景下说出令人不安之语的事实。这三条线索交织在一起，勾勒出AI公司未来必须面对的治理三难困境。</p></blockquote><ol start="3"><li><strong>Claude Mythos &amp; Model Arms Race</strong>：<strong>新模型密集发布，军备竞赛白热化</strong> 社区爆出「Claude Mythos」引发轰动；智谱发布「GLM5.1」全面超越前代；英伟达推出「Nemotron Nano 12B」与「Nemotron 3 Super」系列；Mistral AI发布顶尖语音合成模型「Voxtral TTS」，每千字符仅0.016美元；谷歌「Gemini 3.1 Flash Live」与「Lyria 3 Pro」音乐模型同步上线。 🔗 <strong>Sources:</strong> <strong><a href="https://x.com/billtheinvestor/status/2037802710909788411" target="_blank" rel="noreferrer">[X/billtheinvestor]</a> | <a href="https://x.com/oran_ge/status/2037505953239892153" target="_blank" rel="noreferrer">[X/oran_ge]</a> | <a href="https://x.com/NVIDIAAIDev/status/2036901324156264598" target="_blank" rel="noreferrer">[X/NVIDIAAIDev]</a> | <a href="https://mistral.ai/news/voxtral-tts" target="_blank" rel="noreferrer">[Mistral AI]</a> | <a href="https://blog.google/innovation-and-ai/technology/developers-tools/build-with-gemini-3-1-flash-live/" target="_blank" rel="noreferrer">[Google Blog]</a> | <a href="https://www.xiaohu.ai/c/xiaohu-ai/google-lyria-3-pro-3" target="_blank" rel="noreferrer">[小互AI]</a></strong></li></ol><blockquote><p>💡 <strong>观点：</strong> 模型发布的节奏已经从&quot;季度事件&quot;变成了&quot;每日新闻&quot;。当每家厂商都在宣称&quot;全面超越&quot;时，真正的差异化已经不在模型本身，而在谁能最快将模型能力转化为不可替代的产品体验与生态锁定。</p></blockquote><ol start="4"><li><strong>The Labor Earthquake</strong>：<strong>AI对高技能岗位的冲击进入实质阶段</strong> 研究警告两年内九百万高技能岗位消失；Anthropic第五份经济影响报告预测五年内半数入门白领岗或消失、失业率可能攀升至20%；横店AI短剧占比从7%飙升至38%，单集成本降至500元以下，群演集体失业；沃顿商学院研究揭示人类正陷入「认知投降」——AI出错时高智商者错误跟随率高达79.8%。 🔗 <strong>Sources:</strong> <strong><a href="https://x.com/Kekius_Sage/status/2037870634089214172" target="_blank" rel="noreferrer">[X/Kekius_Sage]</a> | <a href="https://www.aibase.com/zh/news/26555" target="_blank" rel="noreferrer">[AIBase]</a> | <a href="https://www.aibase.com/zh/news/26559" target="_blank" rel="noreferrer">[AIBase]</a> | <a href="https://x.com/rohanpaul_ai/status/2036134704999694835" target="_blank" rel="noreferrer">[X/rohanpaul_ai]</a></strong></li></ol><blockquote><p>💡 <strong>观点：</strong> &quot;认知投降&quot;是本周最值得警惕的信号。它意味着AI的威胁不仅是替代人类的工作，更在于悄悄瓦解人类独立思考的能力——当最聪明的人也开始盲从机器的错误输出时，我们失去的不是岗位，是判断力本身。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kmvja1kwfaq9sq23cs7za9hh.avif" alt="AI资讯：谷歌TurboQuant论文引发学术造假争议的对比分析图" loading="lazy"><br></p></blockquote><ol start="5"><li><strong>GitHub&#39;s Privacy U-Turn</strong>：<strong>GitHub默认使用私有仓库数据训练AI，开发者社区炸锅</strong> GitHub宣布自4月24日起将采集交互数据用于AI训练，即使私有仓库代码也可能被摄取，个人用户须手动关闭才能自保。&quot;默认加入&quot;策略遭到开发者社区强烈反弹。与此同时，开源项目「LiteLLM」遭PyPI供应链投毒攻击，该库累计下载量超九千万次。 🔗 <strong>Sources:</strong> <strong><a href="https://www.aibase.com/zh/news/26576" target="_blank" rel="noreferrer">[AIBase]</a> | <a href="https://newshacker.me/story?id=47531967" target="_blank" rel="noreferrer">[NewsHacker]</a></strong></li></ol><blockquote><p>💡 <strong>观点：</strong> 当代码托管平台开始将你的私有仓库视为训练素材、而开源供应链同时面临投毒攻击时，开发者正被夹在两面火力之间。信任——而非算力——正在成为AI时代最稀缺的资源。</p></blockquote><h3 id="🧰-the-toolbox-开发者工具箱" tabindex="-1">🧰 The Toolbox | 开发者工具箱 <a class="header-anchor" href="#🧰-the-toolbox-开发者工具箱" aria-label="Permalink to &quot;🧰 The Toolbox | 开发者工具箱&quot;">​</a></h3><ol><li><p><strong>DeerFlow 2.0</strong> (🌟44k / 🔗 <strong><a href="https://github.com/bytedance/deer-flow" target="_blank" rel="noreferrer">[GitHub]</a></strong>) <strong>推荐理由</strong>：字节开源的超级智能体框架，整合子代理、沙盒与记忆组件，能自主完成编码与深度调研，处理复杂任务可连续运行数小时。适合需要构建长周期、多步骤自动化研究或开发流水线的团队。</p></li><li><p><strong>hollow-agentOS</strong> (🔗 <strong><a href="https://github.com/ninjahawk/hollow-agentOS" target="_blank" rel="noreferrer">[GitHub]</a> | <a href="https://www.reddit.com/r/artificial/comments/1s66kt0/i_cut_claude_codes_token_usage_by_685_by_giving/" target="_blank" rel="noreferrer">[Reddit讨论]</a></strong>) <strong>推荐理由</strong>：为AI Agent编写的专用操作系统层，将Claude Code的Token消耗降低68.5%。对于正在为Agent运行成本头疼的团队，这不是优化，是&quot;降维打击&quot;级的成本控制方案。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kmvjb3j9faq9sq2y4e4281hp.avif" alt="AI资讯：hollow-agentOS框架大幅降低Token消耗的测试数据对比" loading="lazy"><br></p></li><li><p><strong>Netryx Astra V2</strong> (🔗 <strong><a href="https://www.netryx.live" target="_blank" rel="noreferrer">[官网]</a> | <a href="https://github.com/sparkyniner/Netryx-Astra-V2-Geolocation-Tool" target="_blank" rel="noreferrer">[GitHub]</a></strong>) <strong>推荐理由</strong>：上传一张照片即可精准定位拍摄地点的地理定位工具，源码完全开源。对于OSINT分析、内容溯源、安全审计等场景极具实战价值——同时也是一面照出隐私脆弱性的镜子。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kmvja4j7faq9sq2d6mwveeat.avif" alt="AI资讯：Netryx Astra工具识别照片背景并标注经纬度坐标" loading="lazy"><br></p></li></ol>',16)])])}const b=r(n,[["render",s]]);export{c as __pageData,b as default};
